<?php
namespace App\Http\Controllers;use App\Models\{Teacher,Department};use Illuminate\Http\Request;class TeacherController extends Controller{public function index(Request $r){$q=Teacher::with('department')->where('is_active',true);if($r->filled('department'))$q->where('department_id',$r->integer('department'));return view('teachers.index',['items'=>$q->orderBy('sort')->orderBy('name')->get(),'departments'=>Department::where('is_active',true)->orderBy('sort')->get()]);}public function show(Teacher $teacher){abort_unless($teacher->is_active,404);$teacher->load(['department','students']);$performances=$teacher->performances()->orderByDesc('event_performances.id')->get()->sortByDesc(fn($p)=>$p->event?->starts_at);return view('teachers.show',compact('teacher','performances'));}}